{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Objective Colon capsule endoscopy (CCE) has emerged as a promising alternative for investigating lower gastrointestinal symptoms. However, its adoption has been limited due to concerns about cost- effectiveness, significantly influenced by follow- up endoscopy rates (FERs). Understanding CCE's FERs is crucial for its integration into routine clinical practice.",
      "reason": "The abstract explicitly states the current state (CCE as promising but limited adoption) and identifies an important uncertainty/knowledge gap (impact of follow-up endoscopy rates on cost-effectiveness and integration into practice)."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "The primary aim of the review was to evaluate the FER following CCE. The secondary aims include exploring contributing factors to the FER to guide future research to reduce this rate further.",
      "reason": "The methods state the primary and secondary aims, explaining the importance and need for the review (to evaluate FER and identify factors to reduce it), justifying why the review was conducted."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PARTIAL",
      "chunk_id": "text_11",
      "quote": "A Chinese systematic review was identified during the abstract screening stage; however, none of its referenced studies met the inclusion criteria and were therefore excluded.",
      "reason": "The manuscript reports identification of an existing (Chinese) systematic review and explains that its referenced studies did not meet inclusion criteria, but it does not fully situate the current review as an update/replication of prior reviews or comprehensively discuss how it differs from or adds to prior systematic reviews."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This review addresses a diagnostic procedure (CCE) rather than effects of an intervention; the requirement to describe a proposed mechanism of action for an intervention does not apply."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review does not concern a complex intervention or delivery context requiring a logic model; thus the element is not applicable."
    }
  ],
  "confidence": 85
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PARTIAL",
      "chunk_id": "text_4",
      "quote": "The primary aim of the review was to evaluate the FER following CCE. The secondary aims include exploring contributing factors to the FER to guide future research to reduce this rate further.",
      "reason": "Objectives are explicitly stated (primary and secondary aims are clear), but they are not framed using a recognised question-formulation framework (e.g. PICO, PICOS, PECOS)."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_2",
      "quote": "Objective Colon capsule endoscopy (CCE) has emerged as a promising alternative for investigating lower gastrointestinal symptoms. However, its adoption has been limited due to concerns about cost-effectiveness, significantly influenced by follow-up endoscopy rates (FERs). Understanding CCE's FERs is crucial for its integration into routine clinical practice. We synthesised the evidence to evaluate the overall rate of further investigation in CCE.",
      "reason": "The review addresses rates of follow-up investigations (effectiveness/diagnostic outcome), not comparisons of interventions; therefore PICO-style planned comparisons for intervention effects do not apply."
    }
  ],
  "confidence": 85
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_5",
      "quote": "The search included full-­ text clinical, retrospective, and prospective trials evaluating the use of CCE in patients with any colonic pathology. There were no language restrictions, and all the non-­ English articles were screened with the intention of being translated and included if they met the predefined inclusion criteria. Both adult and paediatric studies were considered, provided they offered clear documentation of follow-­ up investigations after the initial CCE. There were no limitations regarding CCE referral indications, patient recruitment criteria, or pathologies investigated in these studies. However, conference abstracts were excluded due to their high risk of bias. Similarly, review articles, systematic reviews, editorials, study protocols, case reports, and small case series or studies with 10 or fewer participants were excluded.",
      "reason": "The manuscript explicitly lists study characteristics and eligibility rules (study designs: clinical, retrospective, prospective; populations: adult and paediatric; requirement for clear documentation of follow-up investigations; minimum sample size >10; no restrictions on indications/pathologies)."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "The literature search was conducted across EMBASE, MEDLINE, and PubMed databases. Additional studies were identified through manual searches of reference lists from the selected publications. The electronic search covered studies published between January 2004 and August 2024, as CCE was unavailable before 2004. Both Medical Subject Headings (MeSH) and non-­ MeSH terms were included in the search strategy, encompassing keywords such as colonoscopy, sigmoidoscopy, CT scan, conversion, and reinvestigation (see online supplemental table A1 for details). The specific search strings for each database are also provided in the online supplemental appendix. Grey literature and unpublished studies were excluded from the review.",
      "reason": "The review specifies dissemination year limits (Jan 2004–Aug 2024) and states that grey literature/unpublished studies were excluded; combined with other chunks (text_5) it also states no language restrictions and exclusion of conference abstracts, satisfying report-characteristic eligibility criteria."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No explicit statement was found that distinguishes exclusion because outcomes were not measured from exclusion because outcome results were not reported. The evidence does not report this distinction."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_10",
      "quote": "To explore potential sources of heterogeneity, meta-­ regression was performed, analysing prespecified subgroups or covariates, including capsule type, different CCE indications, age, sex, and the proportion of participants with adequate bowel cleansing (%) and complete transit rates (%). Both univariate and multivariate random-­ effects meta-­ regression models were applied to identify covariates significantly contributing to variability across studies. Further subgroup meta-­ analyses were performed for covariates demonstrating statistical significance in the meta-­ regression, and results were visualised using forest to illustrate subgroup effects.",
      "reason": "The manuscript specifies the groups used in syntheses (prespecified subgroups/covariates such as capsule type, indications, age, sex, bowel cleansing, complete transit) and links these to subgroup/meta-regression analyses for the syntheses."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_5",
      "quote": "However, conference abstracts were excluded due to their high risk of bias. Similarly, review articles, systematic reviews, editorials, study protocols, case reports, and small case series or studies with 10 or fewer participants were excluded.",
      "reason": "The authors provide a rationale for at least one notable restriction (conference abstracts excluded because of high risk of bias) and list other excluded report types and size thresholds."
    }
  ],
  "confidence": "85"
}

